function deriveRoot(id) {
  if (!id) return id;
  const m = String(id).match(/^(.+?)-item-/);
  return m ? m[1] : id;
}

const items = $input.all();
if (!items || items.length === 0) return [];

// Group by derived root (not rootOrderId which may be per-item if cron didn't fetch root_order_id)
const groups = new Map();
for (const item of items) {
  const rootId = deriveRoot(item.json.orderId) || item.json.rootOrderId || item.json.orderId;
  if (!groups.has(rootId)) groups.set(rootId, []);
  groups.get(rootId).push(item);
}

const output = [];

for (const [rootId, group] of groups) {
  if (group.length >= 2) {
    for (const item of group) {
      item.json._route = 'sibling';
      output.push(item);
    }
    console.log(`Sibling group ${rootId}: ${group.length} items -> w4.1`);
    continue;
  }

  // Single item in batch — query Supabase for other siblings
  const item = group[0];
  try {
    const res = await this.helpers.request({
      method: 'GET',
      uri: `${supabaseUrl}/rest/v1/orders`,
      qs: { root_order_id: `eq.${rootId}`, select: 'id' },
      headers: {
        apikey: supabaseKey,
        Authorization: `Bearer ${supabaseKey}`,
      },
      json: true,
    });

    const siblingCount = Array.isArray(res) ? res.length : 0;
    if (siblingCount > 1) {
      console.log(`HOLD order ${item.json.orderId} (rootId=${rootId}): ${siblingCount} siblings in DB, only 1 in batch`);
      continue;
    }
  } catch (e) {
    console.warn(`Supabase sibling check failed for ${rootId}, treating as single: ${e.message}`);
  }

  item.json._route = 'single';
  output.push(item);
  console.log(`Single order ${item.json.orderId} (rootId=${rootId}) -> w4`);
}

console.log(`Classify result: ${output.length} forwarded, ${items.length - output.length} held`);
return output;

// Bundle sibling-tagged items into strict { siblingGroup: [...] } payloads for w4.1.
const items = $input.all();
if (!items || items.length === 0) return [];

function firstNonEmpty(...vals) {
  for (const v of vals) {
    if (v === undefined || v === null) continue;
    if (typeof v === 'string') {
      const s = v.trim();
      if (s !== '') return s;
    } else {
      return v;
    }
  }
}

function deriveRoot(id) {
  if (!id) return id;
  const m = String(id).match(/^(.+?)-item-/);
  return m ? m[1] : id;
}

const groups = new Map();
for (const item of items) {
  const j = item.json || {};
  const orderId = firstNonEmpty(j.orderId, j.order_id, j.amazon_order_id, j.amazonOrderId);
  if (!orderId) continue;

  // Always group by shared root, never by item-specific rootOrderId.
  const rootId = firstNonEmpty(deriveRoot(orderId), deriveRoot(j.amazon_order_id), deriveRoot(j.amazonOrderId), j.rootOrderId, j.root_order_id, orderId);
  if (!groups.has(rootId)) groups.set(rootId, []);

  const manifest3Key = firstNonEmpty(
    j.manifest3Key,
    j.three_manifest_url,
    j.manifest3Url,
    j.manifestUrl,
    `book-mvp-simple-adventure/orders/${orderId}/manifests/3-manifest.json`
  );
  const oneManifestUrl = firstNonEmpty(j.oneManifestUrl, j.one_manifest_url, j.oneManifestKey);

  groups.get(rootId).push({
    ...j,
    orderId,
    rootOrderId: firstNonEmpty(deriveRoot(orderId), j.rootOrderId, j.root_order_id, rootId),
    manifest3Key,
    one_manifest_url: oneManifestUrl || null
  });
}

const output = [];
for (const [rootId, siblings] of groups) {
  output.push({ json: { siblingGroup: siblings } });
  console.log(`Bundled ${siblings.length} siblings for rootId=${rootId}`);
}

return output;
